import { ChangeDetectionStrategy, Component, effect, ElementRef, inject, signal, viewChild } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

import { TranslatePipe } from '@ngx-translate/core';

import { CompareSelectComponent } from '../../../components/compare/compare-select/compare-select.component';

import { FetchService } from '../../../services/fetch.service';
import { ProjectStateService } from '../../../services/project-state.service';
import { StyleCardService } from '../../../services/style-card.service';
import { CompareService } from '../compare/compare.service';

//TODO: side-by-side page compare w/ select page tool, differences between EN/FR data (archive etc.), pull out all numbers and compare. AI semantic review.
@Component({
  selector: 'aida-review-languages',
  imports: [TranslatePipe, CompareSelectComponent],
  templateUrl: './review-languages.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ReviewLanguagesComponent {
  private readonly sanitizer = inject(DomSanitizer);
  private readonly projectState = inject(ProjectStateService);
  private readonly compareService = inject(CompareService);
  private readonly fetchService = inject(FetchService);
  protected readonly styleCardService = inject(StyleCardService);

  protected readonly englishHTML = signal<SafeHtml | undefined>(undefined);
  protected readonly frenchHTML = signal<SafeHtml | undefined>(undefined);

  constructor() {
    effect((onCleanup) => {
      const bothPaths = this.projectState.getBothPaths(this.compareService.selectedPage());
      if (!bothPaths) return;
      const version = this.compareService.selectedSource();
      const { owner, repo } = this.projectState.getProject().github;
      const urlEN = this.fetchService.generateUrl(bothPaths.en, version, owner, repo);
      const urlFR = this.fetchService.generateUrl(bothPaths.fr, version, owner, repo);
      let stale = false;
      onCleanup(() => (stale = true));
      this.setHTML(urlEN, urlFR, () => stale);
    });
  }

  async setHTML(urlEN: string, urlFR: string, isStale: () => boolean) {
    const htmlEN = this.toSrcdoc(await this.fetchService.fetchContent(urlEN, 'both'));
    const htmlFR = this.toSrcdoc(await this.fetchService.fetchContent(urlFR, 'both'));
    if (isStale()) return;
    this.englishHTML.set(htmlEN);
    this.frenchHTML.set(htmlFR);
  }

  private toSrcdoc(doc: Document): SafeHtml {
    return this.sanitizer.bypassSecurityTrustHtml('<!DOCTYPE html>' + doc.documentElement.outerHTML);
  }

  private readonly enFrame = viewChild.required<ElementRef<HTMLIFrameElement>>('enFrame');
  private readonly frFrame = viewChild.required<ElementRef<HTMLIFrameElement>>('frFrame');
  private loadedCount = 0;

  private syncing = false;

  onFrameLoad() {
    if (++this.loadedCount < 2) return;
    this.loadedCount = 0;
    const en = this.enFrame().nativeElement;
    const fr = this.frFrame().nativeElement;
    this.link(en, fr);
    this.link(fr, en);
  }

  private source: Window | null = null;
  private timer?: ReturnType<typeof setTimeout>;

  private link(from: HTMLIFrameElement, to: HTMLIFrameElement) {
    const a = from.contentWindow!,
      b = to.contentWindow!;
    a.addEventListener('scroll', () => {
      if (this.source && this.source !== a) return;
      this.source = a;

      const maxA = a.document.documentElement.scrollHeight - a.innerHeight;
      const maxB = b.document.documentElement.scrollHeight - b.innerHeight;
      b.scrollTo(0, maxA > 0 ? (a.scrollY / maxA) * maxB : 0);

      clearTimeout(this.timer);
      this.timer = setTimeout(() => (this.source = null), 100);
    });
  }
}
